wire={'body':b'', 'seen':0}
class Sink(BaseHTTPRequestHandler):
 def log_message(self,*args): pass
 def do_POST(self):
  self.rfile.read(int(self.headers['Content-Length'])); wire['seen']+=1
  self.send_response(200);self.send_header('Content-Type','text/event-stream');self.end_headers();self.wfile.write(wire['body'])
server=ThreadingHTTPServer(('127.0.0.1',0),Sink)
