   status,raw,mime=r.handle('/v1/chat/completions',body,{})
   results['native_public_gateway_admission']={'status':status,'body':raw.decode(),'meter_calls':len(r.calls),'scripted_provider_requests':wire['seen']}
  # Record provider canonical usage and comment-prefixed SSE through actual local HTTP.
  usage={'prompt_tokens':11,'completion_tokens':5,'completion_tokens_details':{'reasoning_tokens':3},'prompt_tokens_details':{'cached_tokens':7},'cost':0.02,'cost_details':{'upstream_inference_cost':0.03},'is_byok':False}
  frame=('data: '+json.dumps({'model':'openai/gpt-4.1','choices':[],'usage':usage})+'\n\ndata: [DONE]\n\n').encode()
  results['sse']={}
  for name,prefix in [('canonical',b''),('comment_prefixed',b': OPENROUTER PROCESSING\n\n'),('event_prefixed',b'event: message\n')]:
   wire['body']=prefix+frame
   meter=Egress({'request_cap':1,'paid_cap_usd':1,'liability_usd_per_dispatch':0.1,'upstreams':cfg['upstreams']},p,'probe','baseline',fixture=True)
   status,raw,mime=meter.forward('public',body,{})
   results['sse'][name]={'status':status,'call':meter.calls[0]}
